mapper.select:
SELECT id, content, image_url, user_id, reply_to_uid,parent_id, created_at FROM ( SELECT id, content, image_url, user_id, reply_to_uid,parent_id, created_at, ROW_NUMBER() OVER (PARTITION BY parent_id ORDER BY id DESC) AS rn FROM comment WHERE parent_id IN
#{id}
AND status = 1 AND deleted_at IS NULL ) ranked WHERE rn <= #{limit} ORDER BY parent_id, id DESC
